import { intlCountryNames, matchCountry, normalize } from '@/lib/job-sources/country'
import citiesByCountry from './cities.json'

// Countries and their main cities for the search Location picker. The picker
// still produces one location string ("Colombo, Sri Lanka" or "Sri Lanka"),
// the same shape the search API and job sources have always taken.
//
// City data: GeoNames (https://www.geonames.org), CC BY 4.0, generated by
// scripts/build-cities.ts.

export interface Country {
  code: string
  name: string
  flag: string
}

const CITIES = citiesByCountry as Record<string, string[]>

// A typed town is capped so "Town, Country" stays inside the search API's
// 100-character location limit. The longest listed city is 32 characters.
export const MAX_CITY_LENGTH = 60

// Intl calls the two Congos "Congo - Kinshasa" and "Congo - Brazzaville", and
// matchCountry leaves them out of its name list (its patterns handle them).
const EXTRA_COUNTRIES: Array<[code: string, name: string]> = [
  ['cd', 'DR Congo'],
  ['cg', 'Congo'],
]

// Territories whose names matchCountry reads as another country ("Caribbean
// Netherlands" → nl, "U.S. Virgin Islands" → us), so a search for them would
// go to the wrong country. Left out of the picker rather than offered wrongly.
const NOT_PICKABLE = new Set(['bq', 'um', 'vi'])

// Words people type for a country that aren't in its name.
const SEARCH_ALIASES: Record<string, string[]> = {
  gb: ['uk', 'britain', 'england', 'scotland', 'wales'],
  us: ['usa', 'america'],
  ae: ['uae', 'emirates'],
  cd: ['drc'],
}

// "Myanmar (Burma)" → "Myanmar", "Hong Kong SAR China" → "Hong Kong".
function displayName(intlName: string): string {
  return intlName.replace(/\s*\(.*\)/, '').replace(/ SAR China$/, '')
}

// The flag emoji for a two-letter code (regional indicator letters).
function flagEmoji(code: string): string {
  return String.fromCodePoint(...code.toUpperCase().split('').map((c) => 0x1f1e6 + c.charCodeAt(0) - 65))
}

let countries: Country[] | null = null

// Every country, A–Z by name.
export function listCountries(): Country[] {
  if (countries) return countries
  const all = [...intlCountryNames().map(([code, name]) => [code, displayName(name)]), ...EXTRA_COUNTRIES]
  countries = all
    .filter(([code]) => !NOT_PICKABLE.has(code))
    .map(([code, name]) => ({ code, name, flag: flagEmoji(code) }))
    .sort((a, b) => a.name.localeCompare(b.name, 'en'))
  return countries
}

export function countryByCode(code: string | null | undefined): Country | undefined {
  if (!code) return undefined
  return listCountries().find((c) => c.code === code)
}

// The country's main cities, biggest first.
export function citiesFor(code: string | null | undefined): string[] {
  return (code && CITIES[code]) || []
}

// The location string for the search: "City, Country", "Country", or "".
export function toLocation(countryCode: string | null | undefined, city?: string | null): string {
  const country = countryByCode(countryCode)
  if (!country) return ''
  const c = city?.trim().slice(0, MAX_CITY_LENGTH).trim()
  return c ? `${c}, ${country.name}` : country.name
}

// Listed city name (normalized) → the countries that list it. Built on first use.
let cityIndex: Map<string, string[]> | null = null

function countriesListing(city: string): string[] {
  if (!cityIndex) {
    cityIndex = new Map()
    for (const [code, names] of Object.entries(CITIES)) {
      for (const name of names) {
        const key = normalize(name)
        cityIndex.set(key, [...(cityIndex.get(key) ?? []), code])
      }
    }
  }
  return cityIndex.get(normalize(city)) ?? []
}

// A free-text location (e.g. the CV's) as a country and, when there is one, a
// city. The city keeps the listed spelling when it's a listed city ("sao
// paulo" → "São Paulo"), otherwise the text as written. With no country in the
// text, a town only one country lists gives that country ("Kandy" → Sri Lanka).
export function fromLocation(text: string | null | undefined): { countryCode?: string; city?: string } {
  if (!text) return {}
  const countryCode = matchCountry(text) ?? undefined
  if (!countryCode) {
    const first = text.split(',')[0].trim()
    const listing = first ? countriesListing(first) : []
    if (listing.length !== 1) return {}
    const city = citiesFor(listing[0]).find((c) => normalize(c) === normalize(first))
    return { countryCode: listing[0], city }
  }
  const parts = text.split(',').map((p) => p.trim()).filter(Boolean)
  const first = parts[0] ?? ''
  const listed = citiesFor(countryCode).find((c) => normalize(c) === normalize(first))
  // One part: a listed city ("London") keeps its city; a country name doesn't.
  if (parts.length < 2) return listed ? { countryCode, city: listed } : { countryCode }
  const country = countryByCode(countryCode)
  if (country && normalize(first) === normalize(country.name)) return { countryCode }
  return { countryCode, city: listed ?? first }
}

// Whether an option's text contains the query, ignoring case and accents.
// Countries also match their code and common aliases ("uk", "usa", "uae").
export function matchesCountry(c: Country, query: string): boolean {
  const q = normalize(query.trim())
  if (!q) return true
  return normalize(c.name).includes(q) || c.code === q || (SEARCH_ALIASES[c.code] ?? []).some((a) => a.startsWith(q))
}

export function matchesCity(name: string, query: string): boolean {
  const q = normalize(query.trim())
  return !q || normalize(name).includes(q)
}

export function filterCountries(list: Country[], query: string): Country[] {
  return list.filter((c) => matchesCountry(c, query))
}

export function filterCities(list: string[], query: string): string[] {
  return list.filter((c) => matchesCity(c, query))
}
